        image: { src: "/academy/cash-flow.jpg", alt: "The Cash Flow Dashboard with Financial health, boxes for Monthly expense budget, Monthly income target and Cash in the bank, and income, expenses and net for this week, this month and year to date", caption: "The Cash Flow Dashboard. It has a Profit by business segment card, which is not in this picture. This is a sample account." },
