        image: { src: "/academy/course-bridge.jpg", alt: "The Bring your buyers over page with a Connect a platform area with a platform menu and Connect button, a Products area saying No products yet, and a Recent sales area saying Nothing yet", caption: "Connect a platform, then choose what happens for each product. This is a sample account." },
